    CatalogItem(id: "hab-gear-head-armoire-crownofdiamonds", name: "Бриллиантовая Корона", rank: "A", desc: "Эта сияющая корона — не просто большая шляпа; это также обострит ваш ум! Увеличивает интеллект на 13. Зачарованный шкаф: набор «Бубновый король» (предмет 2 из 3).", slot: "Голова", statName: "Интеллект", statPoints: 4),
