    CatalogItem(id: "hab-gear-head-armoire-crystalcrescenthat", name: "Хрустальная шляпа в форме полумесяца", rank: "B", desc: "Рисунок на этой шляпе меняется в зависимости от фаз луны. Увеличивает интеллект и восприятие на 7 каждый. Зачарованный шкаф: набор «Хрустальный полумесяц» (предмет 1 из 3).", slot: "Голова", statName: "Интеллект", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-dragontamerhelm", name: "Шлем укротителя драконов", rank: "SS", desc: "Ты очень похож на дракона. Идеальный камуфляж... Увеличивает интеллект на 15. Зачарованный шкаф: набор укротителя драконов (предмет 1 из 3).", slot: "Голова", statName: "Интеллект", statPoints: 5),
    CatalogItem(id: "hab-gear-head-armoire-falconercap", name: "Кепка сокольничьего", rank: "A", desc: "Эта веселая кепка поможет вам лучше понять хищных птиц. Увеличивает интеллект на 10. Зачарованный шкаф: набор сокольничьего (предмет 2 из 3).", slot: "Голова", statName: "Интеллект", statPoints: 4),
    CatalogItem(id: "hab-gear-head-armoire-flutterywig", name: "порхающий парик", rank: "C", desc: "В этом прекрасном напудренном парике вашим бабочкам будет достаточно места, чтобы отдохнуть, если они устанут, выполняя ваши приказания. Увеличивает интеллект, восприятие и силу на 5 каждый. Зачарованный шкаф: комплект развевающегося платья (предмет 2 из 3).", slot: "Голова", statName: "Физическая сила", statPoints: 2),
    CatalogItem(id: "hab-gear-head-armoire-gladiatorhelm", name: "Гладиаторский шлем", rank: "B", desc: "Чтобы быть гладиатором, ты должен быть не только сильным... но и хитрым. Увеличивает интеллект на 7 и восприятие на 7. Зачарованный шкаф: комплект гладиатора (предмет 1 из 3).", slot: "Голова", statName: "Интеллект", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-goldenlaurels", name: "Золотые лавры", rank: "B", desc: "Эти золотые лавры награждают тех, кто победил вредные привычки. Увеличивает Восприятие и Телосложение на 8 каждый. Зачарованный шкаф: комплект золотой тоги (предмет 2 из 3).", slot: "Голова", statName: "Восприятие", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-graduatecap", name: "Кепка выпускника", rank: "B", desc: "Поздравляем! Ваши глубокие мысли заслужили эту шапку мышления. Увеличивает интеллект на 9. Зачарованный шкаф: набор выпускника (предмет 3 из 3).", slot: "Голова", statName: "Интеллект", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-greenfloppyhat", name: "Зеленая шляпа с дискетой", rank: "B", desc: "В эту простую шляпу вшито множество заклинаний, придающих ей великолепный зеленый цвет. Увеличивает Телосложение, Интеллект и Восприятие на 8 каждый. Зачарованный шкаф: независимый предмет.", slot: "Голова", statName: "Интеллект", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-hornedironhelm", name: "Рогатый железный шлем", rank: "B", desc: "Этот рогатый шлем, прочно выкованный из железа, сломать практически невозможно. Увеличивает телосложение на 9 и силу на 7. Зачарованный шкаф: набор рогатого железа (предмет 1 из 3).", slot: "Голова", statName: "Выносливость", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-ironbluearcherhelm", name: "Железный синий шлем лучника", rank: "B", desc: "Упрямый? Нет, ты просто хорошо защищен. Увеличивает Телосложение на 9. Зачарованный шкаф: Набор железного лучника (предмет 1 из 3).", slot: "Голова", statName: "Выносливость", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-jestercap", name: "Кепка шута", rank: "SS", desc: "Колокольчики на этой шляпе могут отвлекать ваших противников, но они просто помогают вам сосредоточиться. Увеличивает восприятие на 15. Зачарованный шкаф: набор шута (предмет 1 из 3).", slot: "Голова", statName: "Восприятие", statPoints: 5),
    CatalogItem(id: "hab-gear-head-armoire-lamplighterstophat", name: "Цилиндр фонарщика", rank: "A", desc: "Эта веселая черная шляпа дополнит ваш ансамбль с лампами! Увеличивает Телосложение на 14.", slot: "Голова", statName: "Выносливость", statPoints: 4),
    CatalogItem(id: "hab-gear-head-armoire-lunarcrown", name: "Успокаивающая лунная корона", rank: "B", desc: "Эта корона укрепляет здоровье и обостряет чувства, особенно в полнолуние. Увеличивает Телосложение на 7 и Восприятие на 7. Зачарованный шкаф: Успокаивающий лунный набор (предмет 1 из 3).", slot: "Голова", statName: "Восприятие", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-merchantchaperon", name: "Торговый сопровождающий", rank: "B", desc: "Эта универсальная шерстяная шапка с запахом наверняка сделает вас самым стильным продавцом на рынке! Увеличивает Восприятие и Интеллект на 7 каждый. Зачарованный шкаф: Набор торговца (предмет 1 из 3).", slot: "Голова", statName: "Интеллект", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-minerhelmet", name: "Шахтерский шлем", rank: "C", desc: "Защитите свою голову от падающих задач! Увеличивает интеллект на 5. Зачарованный шкаф: набор шахтера (предмет 1 из 3).", slot: "Голова", statName: "Интеллект", statPoints: 2),
    CatalogItem(id: "hab-gear-head-armoire-mushroomdruidcap", name: "Грибная шапка друида", rank: "B", desc: "Эта шапка, собранная глубоко в туманном лесу, дает владельцу знания о лекарственных растениях. Увеличивает интеллект на 6 и силу на 7. Зачарованный шкаф: набор грибного друида (предмет 1 из 3).", slot: "Голова", statName: "Физическая сила", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-ogremask", name: "Маска огра", rank: "B", desc: "Ваши враги побегут в горы, когда увидят приближающегося огра! Увеличивает Телосложение и Силу на 7 каждый. Зачарованный шкаф: наряд огра (предмет 1 из 3).", slot: "Голова", statName: "Физическая сила", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-orangecat", name: "Оранжевая шляпа кота", rank: "B", desc: "Эта оранжевая шляпа... мурлычет. И дергает хвостом. И дышит? Да, у тебя на голове просто спящий кот. Увеличивает силу и телосложение на 9 каждый. Зачарованный шкаф: независимый предмет.", slot: "Голова", statName: "Физическая сила", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-plaguedoctorhat", name: "Шляпа чумного доктора", rank: "C", desc: "Настоящая шляпа, которую носят врачи, борющиеся с чумой прокрастинации! Увеличивает силу на 6, интеллект на 5 и телосложение на 5. Зачарованный шкаф: набор чумного доктора (предмет 1 из 3).", slot: "Голова", statName: "Физическая сила", statPoints: 2),
    CatalogItem(id: "hab-gear-head-armoire-ramheaddress", name: "Головной убор Барана", rank: "B", desc: "Этот сложный шлем выполнен в форме головы барана. Увеличивает Телосложение на 9 и Восприятие на 7. Зачарованный шкаф: Набор барана-варвара (предмет 1 из 3).", slot: "Голова", statName: "Выносливость", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-rancherhat", name: "Шляпа ранчера", rank: "C", desc: "Собирайте своих питомцев и ссорьтесь со своими скакунами, надев эту волшебную шляпу владельца ранчо! Увеличивает силу на 5, восприятие на 5 и интеллект на 5. Зачарованный шкаф: набор владельца ранчо (предмет 1 из 3).", slot: "Голова", statName: "Физическая сила", statPoints: 2),
    CatalogItem(id: "hab-gear-head-armoire-redfloppyhat", name: "Красная шляпа с дискетой", rank: "C", desc: "В эту простую шляпу вшито множество заклинаний, придающих ей сияющий красный цвет. Увеличивает Телосложение, Интеллект и Восприятие на 6 каждый. Зачарованный шкаф: независимый предмет.", slot: "Голова", statName: "Интеллект", statPoints: 2),
    CatalogItem(id: "hab-gear-head-armoire-redhairbow", name: "Красный бантик для волос", rank: "C", desc: "Станьте сильным, выносливым и умным, надев этот красивый красный бантик для волос! Увеличивает силу на 5, телосложение на 5 и интеллект на 5. Зачарованный шкаф: набор красного банта для волос (предмет 1 из 2).", slot: "Голова", statName: "Физическая сила", statPoints: 2),
    CatalogItem(id: "hab-gear-head-armoire-royalcrown", name: "Королевская Корона", rank: "A", desc: "Ура правителю, могучему и сильному! Увеличивает силу на 10. Зачарованный шкаф: Королевский набор (предмет 1 из 3).", slot: "Голова", statName: "Физическая сила", statPoints: 4),
    CatalogItem(id: "hab-gear-head-armoire-shepherdheaddress", name: "Головной убор пастуха", rank: "B", desc: "Иногда грифоны, которых вы пасете, любят жевать этот головной убор, но, тем не менее, он делает вас более умным. Увеличивает интеллект на 9. Зачарованный шкаф: комплект пастыря (предмет 3 из 3).", slot: "Голова", statName: "Интеллект", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-swanfeathercrown", name: "Корона из лебединых перьев", rank: "B", desc: "Эта диадема прекрасна и легка, как лебединое перо! Увеличивает интеллект на 8. Зачарованный шкаф: комплект «Танцующий лебедь» (предмет 1 из 3).", slot: "Голова", statName: "Интеллект", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-vermilionarcherhelm", name: "Вермилионский шлем лучника", rank: "A", desc: "Волшебный рубин в этом шлеме поможет вам целиться с лазерной фокусировкой! Увеличивает восприятие на 12. Зачарованный шкаф: набор яркого лучника (предмет 3 из 3).", slot: "Голова", statName: "Восприятие", statPoints: 4),
    CatalogItem(id: "hab-gear-head-armoire-vikinghelm", name: "Викингский шлем", rank: "B", desc: "На этом шлеме нет ни рогов, ни крыльев: врагам слишком легко их схватить! Увеличивает силу на 6 и восприятие на 8. Зачарованный шкаф: набор викингов (предмет 2 из 3).", slot: "Голова", statName: "Восприятие", statPoints: 3),
    CatalogItem(id: "hab-gear-head-armoire-violetfloppyhat", name: "Фиолетовая гибкая шляпа", rank: "C", desc: "В эту простую шляпу вшито множество заклинаний, придающих ей приятный фиолетовый цвет. Увеличивает восприятие на 5, интеллект на 5 и телосложение на 5. Зачарованный шкаф: независимый предмет.", slot: "Голова", statName: "Восприятие", statPoints: 2),
    CatalogItem(id: "hab-gear-head-armoire-woodelfhelm", name: "Шлем лесного эльфа", rank: "A", desc: "Этот шлем из листьев может выглядеть хрупким, но он защитит вас от ненастной погоды и опасных врагов. Увеличивает Телосложение на 12. Зачарованный шкаф: Набор лесного эльфа (предмет 1 из 3).", slot: "Голова", statName: "Выносливость", statPoints: 4),
    CatalogItem(id: "hab-gear-head-armoire-yellowhairbow", name: "Желтый бантик для волос", rank: "C", desc: "Станьте проницательным, сильным и умным, надев этот красивый желтый бантик для волос! Увеличивает восприятие, силу и интеллект на 5 каждый. Зачарованный шкаф: набор желтых бантов для волос (предмет 1 из 2).", slot: "Голова", statName: "Физическая сила", statPoints: 2),
    CatalogItem(id: "hab-gear-head-healer-1", name: "Кварцевый венец", rank: "F", desc: "Украшенный драгоценностями головной убор, позволяющий сосредоточиться на поставленной задаче. Увеличивает интеллект на 2.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-healer-2", name: "Аметистовый венец", rank: "F", desc: "Вкус роскоши для скромной профессии. Увеличивает интеллект на 3.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-healer-3", name: "Сапфировый венец", rank: "D", desc: "Светит, чтобы сообщить страждущим, что их спасение близко. Увеличивает интеллект на 5.", slot: "Голова", statName: "Интеллект", statPoints: 2),
    CatalogItem(id: "hab-gear-head-healer-4", name: "Изумрудная диадема", rank: "C", desc: "Излучает ауру жизни и роста. Увеличивает интеллект на 7.", slot: "Голова", statName: "Интеллект", statPoints: 3),
    CatalogItem(id: "hab-gear-head-healer-5", name: "Королевская диадема", rank: "C", desc: "Для короля, королевы или чудотворца. Увеличивает интеллект на 9.", slot: "Голова", statName: "Интеллект", statPoints: 3),
    CatalogItem(id: "hab-gear-head-mystery-201402", name: "Крылатый шлем", rank: "SS", desc: "Этот крылатый обруч наделяет владельца скоростью ветра! Никакой пользы. Товар для подписчиков, февраль 2014 г.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201405", name: "Пламя разума", rank: "SS", desc: "Сожгите прокрастинацию! Никакой пользы. Товар для подписчиков, май 2014 г.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201406", name: "Корона щупалец", rank: "SS", desc: "Щупальца этого шлема собирают магическую энергию из воды. Никакой пользы. Июнь 2014 г. Товар для подписчиков.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201407", name: "Шлем подводного исследователя", rank: "SS", desc: "Этот шлем позволяет легко исследовать подводный мир! Это тоже делает тебя похожим на рыбу с выпученными глазами. Очень ретро! Никакой пользы. Июль 2014 г. Товар для подписчиков.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201408", name: "Солнечная Корона", rank: "SS", desc: "Эта пылающая корона наделяет своего владельца великой силой воли. Никакой пользы. Август 2014 г. Товар для подписчиков.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201411", name: "Стальной шлем Спортинга", rank: "SS", desc: "Это традиционный шлем, который носят в излюбленном хабитианском виде спорта Балансбол, который заключается в том, чтобы накрыть себя тяжелым защитным снаряжением и затем соблюдать здоровый баланс между работой и личной жизнью..... ПРЕСЛЕДУЕМЫМИ ГИППОГРИФАМИ. Никакой пользы. Ноябрь 2014 г. Товар для подписчиков.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201412", name: "Пингвин Шляпа", rank: "SS", desc: "Кто такой пингвин? Никакой пользы. Товар для подписчиков, декабрь 2014 г.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201501", name: "Звездный шлем", rank: "S", desc: "Созвездия мерцают и кружатся в этом шлеме, направляя мысли владельца к сосредоточению. Никакой пользы. Январь 2015 г. Товар для подписчиков.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201505", name: "Шлем Зеленого Рыцаря", rank: "S", desc: "Зелёное перо на этом железном шлеме гордо развевается. Никакой пользы. Товар для подписчиков, май 2015 г.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201508", name: "Гепард Шляпа", rank: "S", desc: "Эта уютная шапка в виде гепарда очень пушистая! Никакой пользы. Товар для подписчиков, август 2015 г.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201509", name: "Маска оборотня", rank: "S", desc: "Это маска, да? Никакой пользы. Сентябрь 2015 г. Товар для подписчиков.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201511", name: "Бревенчатая Корона", rank: "S", desc: "Посчитайте количество колец, чтобы узнать, сколько лет этой короне. Никакой пользы. Ноябрь 2015 г. Товар для подписчиков.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201512", name: "Зимнее пламя", rank: "S", desc: "Это пламя пылает холодом от чистого разума. Никакой пользы. Товар для подписчиков, декабрь 2015 г.", slot: "Голова", statName: "Интеллект", statPoints: 1),
    CatalogItem(id: "hab-gear-head-mystery-201601", name: "Шлем истинной решимости", rank: "S", desc: "Оставайся решительным, храбрый чемпион! Никакой пользы. Январь 2016 г. Товар для подписчиков.", slot: "Голова", statName: "Интеллект", statPoints: 1),
